BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (702::BIGINT, 'En si el profesor explica bien, el problema es que las clases suelen ser algo aburridas. Algo negativo son los proyectos, no son dificiles pero las instrucciones no son claras y por esto mismo, suelen estarse cambiando aspectos al ultimo minuto. Sube las calificaciones hasta el final.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Da crédito extra', 'Muchos proyectos grupales']::TEXT[], '2026-07-07T00:00:00+00:00'::TIMESTAMPTZ, 'c18a9a517b57bda9d979541c168b4fadc0540e5c8eecb25e949c9636e2b123cb'::TEXT, ARRAY[2965]::BIGINT[]),
    (702::BIGINT, 'Ya es la segunda vez que llevo con este profe y lo mismo de siempre. Es bastante desorganizado, cambia los aspectos del proyecto de manera repentina y califica hasta el puro final cosa que detesto. No es mal profe pero sus clases son muy aburridas y se dedica a leer diapositivas y explicar vagamente'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2026-06-21T00:00:00+00:00'::TIMESTAMPTZ, '6006be75ba3c52b4e730839ad88ac3c9bb063778df10e0cbe856c94b1314f975'::TEXT, ARRAY[2965]::BIGINT[]),
    (702::BIGINT, 'El profesor tiene manejo de todos los temas del curso, eso si las clases son 2 horas de puro escuchar. Algo muy malo de él, es que comunicarse para coordinar algo es imposible, le tuve que escribir como 5 veces para coordinar algo, en si no es mal profe, pero tampoco el mejor.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-14T00:00:00+00:00'::TIMESTAMPTZ, '510462a98c8eb43d43844c05d07d2376a9916931d04c9d21f087738ce0d7f7e1'::TEXT, ARRAY[2963]::BIGINT[]),
    (702::BIGINT, 'No tiene mucho sentido escribir este mensaje de por sí no tienen otra opción… pero para informar… este profesor es imposible de contactar… parece que el atender consultas no es parte de su trabajo… Enseñando si es súper bueno … pero calificando… sin comentarios…'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-10T00:00:00+00:00'::TIMESTAMPTZ, '9e634ff73bf51c228354d20db8cc2b7cf8af6a6d63cda865db74a44ecaa02c2b'::TEXT, ARRAY[2972]::BIGINT[]),
    (702::BIGINT, 'Súper negligente con la clase. No responde mensajes y las notas parecen al azar porque no hay rúbrica. Entrega todo al final (ni califica el). Hubiera sido mejor leer el libro. Para un curso así, mejor nada. Parece que ni le gusta ser profesor, pero nadie más da el curso.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-10T00:00:00+00:00'::TIMESTAMPTZ, 'ed1971a323738c9211d897ea61e927c4f3a6fbbba5fd010e9c43232759d02c9f'::TEXT, ARRAY[2972]::BIGINT[]),
    (702::BIGINT, 'Es un profesor regular, califica más o menos duro, y no califica código, sino cumplimiento de requerimientos. Las clases son extremadamente cansadas ya que casi siempre serán teóricas. Un aspecto bueno puede ser que el profe tiene mucha experiencia entonces sabe de lo que habla, pero el curso es zzz'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2025-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'a16bf2d4347d81be9046f87f690e9b6c3ea72c4876006792c093c14ab5fd09f9'::TEXT, ARRAY[2963]::BIGINT[]),
    (702::BIGINT, 'Tiene un buen conocimiento de la materia, y en la mayoría de las veces, sabe explicarla muy bien. Se le nota interés porque los estudiantes aprendan. Lo único que le resto es que puede ser despistado, se atrasa mucho con las notas, y es difícil contactarlo. Si tiene dudas, mejor espere a la clase'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2025-12-03T00:00:00+00:00'::TIMESTAMPTZ, '755338e616e4d4fab48e8f93016db003417675914616b04d5c4698e45a46cfac'::TEXT, ARRAY[2972]::BIGINT[]),
    (702::BIGINT, 'Profe de lo más chill, aunque muchas veces sus clases son un completo bostezo y si tienes alguna pregunta super sencilla, se enreda él solo y te dura 30 mins en responderla y al final te quedas con la misma duda, pero el curso lo hace super fácil y se nota que trata de ayudar en todo lo posible'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2025-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'fe0156c358cfd264faf0627a36129d36d2e1b6ecd2b544e9d153801933392c53'::TEXT, ARRAY[2972]::BIGINT[]),
    (702::BIGINT, 'El profe es un amor, se ve que le apasiona lo que hace, le gusta explicar en la pizarra y eso ayuda mucho a entender mejor los temas, siempre dispuesto a aclarar dudas de una manera amable. La materia es complicada, por lo que se debe llevar al día, principalmente con el proyecto.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'f528a53163fe3be75c45401fe7cd32d736a0858ba62d100ea267470db706ada8'::TEXT, ARRAY[2972]::BIGINT[]),
    (702::BIGINT, 'El profe es paciente y bueno para explicar y muy amable. Personalmente la materia del curso me pareció densa y requería de tiempo, pero el profe en sí hizo la experiencia más provechosa. Atento a resolver sus dudas, y bastante comprensivo si surgen situaciones.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'c3a8bea01e6d8db7f4fa35e6f26dd036531ec919adb1bdeed891772f1c306a70'::TEXT, ARRAY[2972]::BIGINT[]),
    (702::BIGINT, 'Muy buen profe! Ayuda bastante y repite las veces necesarias hasta que se entienda el tema. Es muy flexible con las fechas de entregas. En sí, se nota su interés en que los estudiantes aprendan. Súper recomendado!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'db4036b5d5cd444b5f512345bf75c4279a5b531e2702b41f76df96b32112a865'::TEXT, ARRAY[1890]::BIGINT[]),
    (702::BIGINT, 'Es un buen profe, explica muy bien y está dispuesto a ayudar a los estudiantes si se lo piden. Las clases son muy aburridas y peor que son en la noche, el proyecto es sólo uno pero es complicado, no lo deje para el final.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'c374d3dd1c0712509a3b5d419b7acde5e7d88fbf67915430a2c06a2ca16f7ae0'::TEXT, ARRAY[2972]::BIGINT[]),
    (702::BIGINT, 'La materia es sumamente aburrida y el hecho de que usualmente es en la noche no ayuda. Marco es buen profe explica las veces que se ocupen y es muy paciente. Las evaluaciones no son difíciles solo repase antes. Administra mal el tiempo entonces al final es pesadísimo en especial el proyecto'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2022-06-18T00:00:00+00:00'::TIMESTAMPTZ, '59a959c4c5b81b558e02cdb9901ddc6cb153b9c79ff8a66bbe6ee7bb1f60262e'::TEXT, ARRAY[2972]::BIGINT[]),
    (702::BIGINT, 'Esperaba mucho más del curso. La materia es muy aburrida, y él no la hace interesante, pero es buen profe. Bastante paciente, siempre busca ayudar. Deja un proyecto muy fuck así que no lo dejen para el final. Aunque da más tiempo para la entrega si se le pide'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2021-06-29T00:00:00+00:00'::TIMESTAMPTZ, '55ea60a666c523d8bc6a96e7eb97acbe3bb81fd52e3b89ec1a20127d1f1b3c0d'::TEXT, ARRAY[2972]::BIGINT[]),
    (702::BIGINT, 'El profe enseña bien y es muy pura vida. En las revisiones le interesa la funcionalidad general y la parte de bases de datos, califica suave pero a veces pide cosas que no decia la especificacion. Los quices son kahoots y son faciles.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-12T00:00:00+00:00'::TIMESTAMPTZ, '0501e75f51f63a7c1addede19bdec8705f6901ad4af776f57d35d6579d1d18f2'::TEXT, ARRAY[2970]::BIGINT[]),
    (702::BIGINT, 'Buen profesor, temas aburridos. No pareciera que haya rúbrica de calificación y al final solo presenta todas las notas de golpe'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'c0f69991d4fd2e83b021696081db4c1989d98a9e7cd69dd97a605db18a6523e4'::TEXT, ARRAY[2972]::BIGINT[]),
    (702::BIGINT, 'Excelente profesor, se interesa en el aprendizaje de los estudiantes. Los proyectos tienen un alto nivel de complejidad y creatividad, Realiza quices todas las semanas, sin excepción.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2019-12-09T00:00:00+00:00'::TIMESTAMPTZ, '7f5eff18b95742bf47bd2e3ecb3fff52fa67a262af3cca6927b1e477433d4b4d'::TEXT, ARRAY[2972]::BIGINT[]),
    (702::BIGINT, 'No es malo, muy aburrido pero es colaborador'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'a8b21be12a10ad4d3aaa5596a23c956c21effad274952e116ee81d0594f863eb'::TEXT, ARRAY[2972]::BIGINT[]),
    (702::BIGINT, 'Es un poco aburrido en sí. Los proyectos son muy interesantes y se pone muy creativo. Es un buen profe en general'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación']::TEXT[], '2018-05-23T00:00:00+00:00'::TIMESTAMPTZ, '73c3f46a40165860df0dff91521a6129ca4593bef3b830b7f83d0c988bdbddb5'::TEXT, ARRAY[2972]::BIGINT[]),
    (702::BIGINT, 'Exelente profesor, los proyectos son largos pero con un buen grupo de trabajo y poniendole ganas se pasa el curso fácil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-10-14T00:00:00+00:00'::TIMESTAMPTZ, 'b53ca7cbecf51804f3fb5ec07f0f4537d4a204a199d1a080b64fe71787d597c5'::TEXT, ARRAY[2970]::BIGINT[]),
    (702::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2017-07-10T00:00:00+00:00'::TIMESTAMPTZ, '25a52b0ef5eb760fa10663e72d3153b823e1129a03853c42fc3879ca0d7d5e30'::TEXT, ARRAY[2972]::BIGINT[]),
    (702::BIGINT, 'Lee de diapositivas, eso es lo aburrido, explica hasta que entiendas, se enreda en ocasiones, quiz una vez por semana de dificultad intermedia, proyectos algo caros en ocasiones pero es flexible en general.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros']::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, '8736e0450b470663ea8497812736b9dcc60a79c90f5eda0db9fc7d10ab997d17'::TEXT, ARRAY[2972]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
